function getExpirationDate(selectedExpiration, customDateTime) {
	const now = /* @__PURE__ */ new Date();
	switch (selectedExpiration) {
		case "never": return;
		case "24hours":
			now.setHours(now.getHours() + 24);
			return now.toISOString();
		case "14days":
			now.setDate(now.getDate() + 14);
			return now.toISOString();
		case "30days":
			now.setDate(now.getDate() + 30);
			return now.toISOString();
		case "custom":
			if (!customDateTime) return void 0;
			try {
				return new Date(customDateTime).toISOString();
			} catch (error) {
				console.error("Failed to parse custom date/time:", error);
				return;
			}
		default: return;
	}
}
